function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // kiwi
  ctx.fillStyle = 'brown';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // fuzzy
  ctx.lineWidth = 2;
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2 + 50 + Math.sin(t + i) * 10, H/2 + Math.cos(t + i) * 10);
    ctx.lineTo(W/2 + 50 + Math.sin(t + i) * 20, H/2 + Math.cos(t + i) * 20);
    ctx.stroke();
  }

  // cutting
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2);
  ctx.lineTo(W/2 + 20, H/2);
  ctx.stroke();

  // green inside
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30 + Math.sin(t) * 10, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
